values('TRANSACTIONS_QUARTERLY_COUNT','Operaciones trimestrales declaradas','BUSINESS_ACTIVITY','COUNT','transactions',null,'SAME_METRIC',true,'Número de operaciones/transacciones declarado para un trimestre o ventana trimestral. No equivale a volumen monetario.',25)
