with vals(fintech_id,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url,psav_basis,psav_conf) as (
 values
 ('ENT-RUT-76905736-6','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Ripio mantiene una app para usuarios y una oferta Ripio Business/Crypto as a Service para instituciones, bancos, fintechs y empresas.','La oferta vigente atiende simultáneamente personas y organizaciones mediante productos diferenciados.','Ripio publica comisión de 0,5% para compra/venta de criptomonedas, con excepciones específicas como BTC.','https://www.ripio.com/es/cl','Evidencia funcional abierta confirma compra/venta cripto, infraestructura fiat-cripto, trading/custodia y servicios para usuarios y empresas en Chile/LATAM.',0.999::numeric),
 ('ENT-RUT-76590133-2','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.99::numeric,0.99::numeric,0.999::numeric,'CryptoMarket/NotBank admite usuarios personas y cuentas institucionales para personas jurídicas; la plataforma combina exchange, wallet y servicios financieros cripto.','La documentación de cumplimiento contempla clientes persona natural y persona jurídica/cuenta institucional.','CryptoMarket publica tarifas por transacción/servicio, incluyendo Simple 1,5% y comisiones de trading/retiro según producto.','https://www.cryptomkt.com/es-cl/legal','Evidencia funcional y legal del Grupo CryptoMarket confirma compra/venta, wallet/custodia, conversión fiat-cripto y servicios cripto; el vehículo chileno CryptoMKT SpA procesa CLP y Dysopsis Limited Agencia en Chile presta/solicita servicios regulados de custodia/intermediación/SAT.',0.999::numeric),
 ('ENT-RUT-76949499-5','B2C','PERSONAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'SatoshiTango ofrece en Chile compra/venta, billetera y rendimientos cripto orientados principalmente a usuarios personas.','La comunicación, onboarding y oferta observada se dirige principalmente a personas/inversionistas individuales.','Los términos y páginas de producto publican comisión de 1% para compraventa fiat-cripto y 0,5% para compraventa cripto-cripto.','https://www.satoshitango.com/cl','La oferta Chile confirma compra/venta con moneda local, wallet, transferencias/retiros por redes y stablecoins; funcionalmente corresponde a servicios de activos virtuales.',0.999::numeric),
 ('ENT-RUT-77091316-0','B2B2C','AMBOS',null,0.999::numeric,0.999::numeric,null,'Nizzo declara soluciones para usuarios particulares, PYMES, startups y empresas, combinando cambio fiat-cripto y pagos internacionales.','Los términos aceptan personas y entidades legales como clientes de la plataforma.',null,'https://www.nizzocap.com/es','Términos vigentes de Nizzo Capital SpA confirman compra, venta e intercambio de activos digitales y pagos/transferencias nacionales e internacionales.',0.999::numeric)
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_DIGITAL_ASSETS_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,coalesce(v.revenue_model,e.revenue_model),coalesce(v.rev_conf,e.revenue_model_confidence),1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'psav_basis',v.psav_basis,'manual_validation',true,'cohort','DIGITAL_ASSETS')
 from vals v join public.aml_fintech_entity e using(fintech_id)
 returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=coalesce(v.revenue_model,e.revenue_model),business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=case when v.revenue_model is not null then v.rev_basis else e.revenue_model_basis end,revenue_model_confidence=case when v.revenue_model is not null then v.rev_conf else e.revenue_model_confidence end,profile_classifier_version='MANUAL_OFFICIAL_DIGITAL_ASSETS_2026_09_09',profile_refreshed_at=now(),psav_status='CONFIRMED',psav_basis=v.psav_basis,psav_confidence=v.psav_conf,psav_refreshed_at=now(),refreshed_at=now()
from vals v
where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

