update public.aml_fintech_entity set psav_status='EXPOSURE',psav_basis='Octopus Digital Distribution SpA figura públicamente como SO UAF y su marca ChileBitcoin mantiene presencia vinculada a Bitcoin/activos digitales; la web actual sólo muestra precio BTC/CLP y no permite confirmar por sí sola una función PSAV transaccional vigente.',psav_confidence=0.75,psav_refreshed_at=now(),refreshed_at=now() where fintech_id='ENT-RUT-76626762-9';

values('ENT-RUT-76590133-2','59248990-2','ENT-RUT-59248990-2','DYSOPSIS LIMITED AGENCIA EN CHILE','REGULATED_SERVICE_PROVIDER',false,'CMF','LEY_FINTEC_NCG502_APPLICATION','COMPANY_OFFICIAL','https://www.notbank.com/es-cl/legal','Los términos vigentes de NotBank/Grupo CryptoMarket señalan que Dysopsis Limited Agencia en Chile es la entidad constituida bajo NCG 502 que solicitó registro/autorización para custodia, intermediación y sistema alternativo de transacción, y que presta el servicio de custodia a clientes en Chile.',0.999,now(),now(),jsonb_build_object('group','CryptoMarket/NotBank','status_note','solicitud en evaluación según términos vigentes','service_split','CryptoMKT SpA procesa/recauda CLP; Dysopsis presta custodia y solicita servicios Ley Fintec'))
