select 'ENTITY','ENT-RUT-76590133-2','OPERATED_BY','59248990-2','ENT-RUT-59248990-2','DYSOPSIS LIMITED AGENCIA EN CHILE','2025-01-17','COMPANY_OFFICIAL','https://www.notbank.com/es-cl/legal','Para servicios de custodia y servicios Ley Fintec en Chile, los términos del Grupo CryptoMarket/NotBank identifican a Dysopsis Limited Agencia en Chile como entidad prestadora/solicitante; CryptoMKT SpA mantiene rol de procesamiento y recaudo de CLP.',0.999,true,now(),now(),jsonb_build_object('scope','regulated_fintech_services','not_identity_merge',true)
